"""Convert between integers 1..3999 and canonical upper-case Roman numerals such as "MCMXCIV"."""
import re

_NUMERALS = [
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
]

# Only the canonical shape: at most three M, then each decimal place as one of its standard forms.
_CANONICAL = re.compile(r"M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})")


def to_roman(n):
    """Upper-case Roman numeral for n, which must be an integer from 1 to 3999."""
    if isinstance(n, bool) or not isinstance(n, int) or not 1 <= n <= 3999:
        raise ValueError(f"must be an integer from 1 to 3999: {n!r}")
    parts = []
    for value, numeral in _NUMERALS:
        count, n = divmod(n, value)
        parts.append(numeral * count)
    return "".join(parts)


def from_roman(s):
    """Integer for a canonical upper-case Roman numeral, such as the strings to_roman produces."""
    if not isinstance(s, str) or not s or _CANONICAL.fullmatch(s) is None:
        raise ValueError(f"not a canonical Roman numeral: {s!r}")
    total = 0
    i = 0
    for value, numeral in _NUMERALS:
        while s.startswith(numeral, i):
            total += value
            i += len(numeral)
    return total

