import contextlib
import io
import unittest

from textkit.cli import main
from textkit.roman import from_roman, to_roman


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class RomanTest(unittest.TestCase):
    def test_to_roman_examples(self):
        self.assertEqual(to_roman(1), "I")
        self.assertEqual(to_roman(4), "IV")
        self.assertEqual(to_roman(1994), "MCMXCIV")
        self.assertEqual(to_roman(3999), "MMMCMXCIX")

    def test_to_roman_rejects_out_of_range(self):
        for n in (0, -1, 4000):
            with self.subTest(n=n):
                with self.assertRaises(ValueError):
                    to_roman(n)

    def test_from_roman_examples(self):
        self.assertEqual(from_roman("MCMXCIV"), 1994)
        self.assertEqual(from_roman("MMMCMXCIX"), 3999)

    def test_from_roman_rejects_non_canonical(self):
        for s in ("IIII", "IC", "VX", "mcm", "", "MMMM", "IM", "VV", "XXXX", "ABC", "I I"):
            with self.subTest(s=s):
                with self.assertRaises(ValueError):
                    from_roman(s)

    def test_round_trip_every_value(self):
        for n in range(1, 4000):
            with self.subTest(n=n):
                self.assertEqual(from_roman(to_roman(n)), n)


class RomanCliTest(unittest.TestCase):
    def test_digits_print_numeral(self):
        self.assertEqual(run("roman", "1994"), (0, "MCMXCIV\n", ""))

    def test_numeral_prints_integer(self):
        self.assertEqual(run("roman", "MCMXCIV"), (0, "1994\n", ""))

    def test_invalid_numeral_exits_2(self):
        code, out, err = run("roman", "IIII")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "))

    def test_out_of_range_digits_exit_2(self):
        code, out, err = run("roman", "0")
        self.assertEqual(code, 2)
        self.assertTrue(err.startswith("error: "))


if __name__ == "__main__":
    unittest.main()

